WITH mutation_result AS (UPDATE "cf_select"."items" SET "label" = $1::text WHERE items."id" = $2::int4 RETURNING *) SELECT json_build_object('returning', (SELECT COALESCE(json_agg(row_to_json("_e")), '[]'::json) FROM (SELECT "cf_select"."item_label"("item" := ROW("mutation_result"."id", "mutation_result"."owner_id", "mutation_result"."label", "mutation_result"."amount", "mutation_result"."payload")::"cf_select"."items") AS "item_label", "cf_select"."item_second"("multiplier" := $3::"pg_catalog"."int4", "item" := ROW("mutation_result"."id", "mutation_result"."owner_id", "mutation_result"."label", "mutation_result"."amount", "mutation_result"."payload")::"cf_select"."items") AS "item_second" FROM mutation_result) AS "_e"))
